-- Dashboard and BI reporting queries: daily revenue, funnels, top-N
SELECT toDate(created_at) AS day, sum(total) AS revenue, count() AS orders FROM orders GROUP BY day ORDER BY day;
SELECT toStartOfMonth(created_at) AS month, sum(total) AS revenue FROM orders WHERE created_at >= now() - INTERVAL 12 MONTH GROUP BY month ORDER BY month;
SELECT toStartOfHour(ts) AS hour, count() AS hits FROM web_events WHERE ts >= now() - INTERVAL 1 DAY GROUP BY hour ORDER BY hour;
SELECT toStartOfInterval(ts, INTERVAL 5 MINUTE) AS bucket, count() FROM web_events GROUP BY bucket ORDER BY bucket;
SELECT country, uniq(user_id) AS users, uniqExact(session_id) AS sessions FROM web_events GROUP BY country ORDER BY users DESC LIMIT 10;
SELECT quantile(0.9)(latency_ms) AS p90, quantile(0.99)(latency_ms) AS p99 FROM requests;
SELECT quantiles(0.5, 0.9, 0.99)(latency_ms) FROM requests WHERE ts > now() - INTERVAL 1 HOUR;
SELECT endpoint, quantileTDigest(0.95)(latency_ms) AS p95, avg(latency_ms), max(latency_ms) FROM requests GROUP BY endpoint ORDER BY p95 DESC;
SELECT sumIf(total, status = 'paid') AS paid, sumIf(total, status = 'refunded') AS refunded FROM orders;
SELECT countIf(status = 'error') / count() AS error_rate FROM requests;
SELECT avgIf(latency_ms, status < 500) FROM requests;
SELECT uniqIf(user_id, event = 'purchase') AS buyers, uniqIf(user_id, event = 'view') AS viewers FROM web_events;
SELECT category, argMax(name, price) AS priciest, argMin(name, price) AS cheapest FROM products GROUP BY category;
SELECT groupArray(name) AS names, groupUniqArray(category) FROM products;
SELECT user_id, topK(3)(page) AS top_pages FROM web_events GROUP BY user_id;
SELECT windowFunnel(3600)(ts, event = 'view', event = 'cart', event = 'purchase') AS level, count() FROM web_events GROUP BY user_id;
SELECT product_id, sum(qty) AS units FROM order_items GROUP BY product_id ORDER BY units DESC LIMIT 10;
SELECT date, sum(amount) FROM sales GROUP BY date WITH TOTALS ORDER BY date;
SELECT region, product, sum(amount) FROM sales GROUP BY region, product WITH ROLLUP;
SELECT region, product, sum(amount) FROM sales GROUP BY region, product WITH CUBE;
SELECT a, b, count() FROM t GROUP BY ROLLUP(a, b);
SELECT formatReadableSize(sum(bytes)) AS size, formatReadableQuantity(count()) FROM files;
SELECT round(avg(total), 2), round(stddevPop(total), 2), median(total) FROM orders;
SELECT toYYYYMM(created_at) AS ym, count() FROM orders GROUP BY ym ORDER BY ym DESC LIMIT 12;
SELECT dateDiff('day', min(created_at), max(created_at)) FROM orders;
SELECT toDate(ts) AS d, count() FROM web_events WHERE ts >= toStartOfDay(now()) - INTERVAL 7 DAY AND ts < toStartOfDay(now()) GROUP BY d;
SELECT d, c, sum(c) OVER (ORDER BY d) AS running FROM (SELECT toDate(ts) AS d, count() AS c FROM web_events GROUP BY d) ORDER BY d;
SELECT number FROM numbers(10);
SELECT toDate('2024-01-01') + number AS d FROM numbers(30);
SELECT 1 + 2 * 3 AS x, (1 + 2) * 3 AS y, 10 % 3 AS z, -5 AS neg;
SELECT arrayJoin([1, 2, 3]) AS n;
